function range(id,label,value,min,max,step){return `<label>${label}<output>${value}</output><input data-opt="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;}
function number(id,label,value,min,max,step=1){return `<label>${label}<input data-opt="${id}" type="number" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;}
function check(id,label,value){return `<label class="check"><input data-opt="${id}" type="checkbox" ${value?'checked':''}>${label}</label>`;}
function select(id,label,values,value){return `<label>${label}<select data-opt="${id}">${values.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select></label>`;}
