function programChecklist(key,title,items,selected){return `<details class="program-picker" ${key==='quarters'?'open':''}><summary>${title} <span id="${key}Count">${selected.length}/${items.length}</span></summary><input class="program-search" type="search" data-program-filter="${key}" placeholder="Filter types…" aria-label="Filter ${title}"><p class="micro">${key==='quarters'?'Every checked type appears at least once. Unchecked types are excluded.':'Allowed building types, filtered by each quarter’s program. A type is only placed in a compatible quarter.'}</p><div class="program-actions"><button type="button" data-program="${key}" data-choice="all">All</button><button type="button" data-program="${key}" data-choice="none">None</button>${key==='quarters'?'<button type="button" data-program="quarters" data-choice="default">Default city</button>':''}</div><div class="program-grid">${items.map(x=>`<label class="check"><input type="checkbox" data-subset="${key}" value="${R.esc(x.id)}" ${selected.includes(x.id)?'checked':''}>${R.esc(x.name)}</label>`).join('')}</div></details>`;}
