function optPane(id,active,content){return `<div class="opt-pane" role="tabpanel" data-opt-pane="${id}"${id===active?'':' hidden'}>${content}</div>`;}
function selectOptTab(id){optTabState[mode]=id;qa('[data-opt-tab]').forEach(b=>{const on=b.dataset.optTab===id;b.classList.toggle('active',on);b.setAttribute('aria-selected',on);});qa('[data-opt-pane]').forEach(p=>p.hidden=p.dataset.optPane!==id);}
function pickTab(m,tabs){const saved=optTabState[m];return tabs.some(t=>t[0]===saved)?saved:tabs[0][0];}
