 if(mode==='region'){tabs.push(['landform','Landform'],['settlements','Settlements']);const a=pickTab(mode,tabs);h=`<div class="scope-note"><b>Campaign region</b>Settlement and landmark symbols are schematic. For a landscape-first, settlement-free survey, choose <b>Local region</b>.</div>`+optTabBar(tabs,a)+optPane('landform',a,number('sizeKm','Width & height (km)',o.sizeKm,2,100)+select('terrain','Landform',PRESETS.region.map(p=>[p[0],p[1]]),o.terrain)+range('water','Water level',o.water,.1,.7,.01)+range('ruggedness','Ruggedness',o.ruggedness,0,1,.05)+range('forest','Forest cover',o.forest,0,1,.05))+optPane('settlements',a,`<div class="two-col">${number('settlements','Settlements',o.settlements,2,30)}${number('poi','Adventure sites',o.poi,0,40)}</div>`);}
