 qa('[data-program]').forEach(b=>b.onclick=()=>{const key=b.dataset.program,values=b.dataset.choice==='all'?(key==='quarters'?E.QUARTERS:E.BUILDING_TYPES).map(x=>x.id):b.dataset.choice==='default'?E.defaults.city[key]:[];qa(`[data-subset="${key}"]`).forEach(x=>x.checked=values.includes(x.value));optionsByMode[mode]=getOptions();programCounts();});
