 const b=document.createElement('button');b.className='full';b.textContent='Regenerate this district';b.disabled=!!f.locked;b.onclick=()=>{const before=JSON.stringify(scene());try{E.regenerateDistrict(scene(),f.id,select.value);E.validateScene(scene());history().push(before);changed('Quarter regenerated with its building program; other quarters and locked objects preserved.',true);}catch(e){maps[active]=JSON.parse(before);render();status('Could not regenerate this quarter: '+e.message);}};host.append(b);
