function openDatabase(name='megamap-offline-v2'){return new Promise(resolve=>{try{const req=indexedDB.open(name,1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);req.onblocked=()=>resolve(null);setTimeout(()=>resolve(null),1500);}catch{resolve(null);}});}
function latestProject(database){return new Promise(resolve=>{try{const tx=database.transaction('projects','readonly'),req=tx.objectStore('projects').get('latest');req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);}catch{resolve(null);}});}
/* One-time read of the previous V1 local autosave. The next autosave copies it
 * into the current storage; the old record is never modified or deleted. */
async function legacyAtlas(){try{const old=await openDatabase('megamap-offline-v1');if(old){const data=await latestProject(old);old.close&&old.close();if(data)return data;}}catch{}try{return JSON.parse(localStorage.getItem('megamap-atlas-v1')||'null');}catch{return null;}}
async function boot(){setBusy(true,'Opening your local workspace…');try{db=await openDatabase();let saved=null;if(db)saved=await latestProject(db);if(!saved)try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}if(!saved)saved=await legacyAtlas();
 if(saved){try{const data=C.validateAtlas(saved);maps=data.maps;library=data.library;active=data.active;}catch(e){status('Local recovery was invalid: '+e.message);}}
 if(!maps.length)maps=[E.generate('region','silver-vale-42',{})];maps.forEach(ensure);activate(active);$('assetCount').textContent=A.catalog.length+library.length;status('Ready · save an atlas backup before closing. Start with a preset or edit the map.');
 }catch(e){status('Startup failed: '+e.message);}finally{setBusy(false);}}
boot();
